    async def assign_task_to_person(
        self,
        task_id: str,
        *,
        person_id: str,
        extra_body: Optional[Mapping[str, Any]] = None,
    ) -> AssignTaskToPersonResponse:
        """Assign a task to a person.

        Add a person to the assignees of a task. The route also adds the person to the
        team of the project. An administrator or a manager of the project can assign all
        the tasks. A supervisor without department can assign all the tasks. A
        supervisor with departments can assign the tasks of their departments, to a
        person of one of their departments. Other users can assign themselves to the
        tasks of their departments. You cannot assign a bot, except when the project
        enables bot collaboration.

        Args:
            task_id: Unique identifier of the task

        ``PUT /actions/tasks/{task_id}/assign``
        """
        return await self._t.request(
            "PUT",
            "/actions/tasks/{task_id}/assign",
            path_params={"task_id": task_id},
            body={"person_id": person_id},
            extra_body=extra_body,
            body_mode="json_props",
            response_type=AssignTaskToPersonResponse,
        )

